a['impacts']=[]
def add(r,rule,state,reason,action_ids=(),extra=()):
    iid='IMP-'+r['system_id']+'-'+rule.removeprefix('RULE-').removeprefix('POL-')
    links=list(action_ids);known=[calendar_map[x] for x in links if x in calendar_map]
    a['impacts'].append(rec(iid,reason,evidence=[rule,'FACT-'+r['system_id'],source('CALENDAR')['id'],*extra],
        system_id=r['system_id'],rule_ref=rule,state=state,reason=reason,owner=r['owner'],
        proposed_action='; '.join(x+': '+calendar_map[x]['action'] if x in calendar_map else x+': Confirm publication purpose and editorial responsibility; date pending Operations' for x in links),
        proposed_due_date=known[0]['due_date'] if known else None,approval_status='pending',action_ids=links,
        legal_dependency=rule.startswith('RULE'),observation_basis='Current source reports describing August26; historical proof limits retained'))
for r in systems:
    sid=r['system_id']
    for rule in ['RULE-50-1','RULE-50-2']:
        if sid=='AI-005':
            add(r,rule,'unresolved','Current development, commissioning and branding facts are missing. The stale provider questionnaire cannot establish the actor or current-release scope; human adjudication does not repair this gap.',['ACT-005'],['GAP-005','REC-005','RULE-ROLE','TIME-MARKING'])
        else:
            reason='Reported third-party licensed use supports no additional Quillhaven provider duty under this paragraph; inventory names are not product brands. Supplier duties and company policy remain separate. Final Legal interpretation is pending.'
            if rule=='RULE-50-2' and sid in ['AI-003','AI-008']:reason+=' June1 supplier product entry supports a conditional supplier-only December2 transition; it does not postpone deployer disclosure or August policy.'
            add(r,rule,'supported-no-impact',reason,extra=['RULE-ROLE','TIME-MARKING']+(['FACT-MARKET-003-008'] if sid in ['AI-003','AI-008'] else []))
    if sid=='AI-005':
        add(r,'RULE-50-3','unresolved','Whether current flagging infers emotions or personal categories from biometric data is unknown. Human review is not an Article50(3) exemption. Legal needs refreshed technical facts.',['ACT-005'],['GAP-005','REC-006'])
    else:
        add(r,'RULE-50-3','supported-no-impact','The captured use description concerns conversation, drafting, illustration, pronunciation, summaries or localisation; no emotion recognition or biometric categorisation is established for this described use. This bounded proposal is not a finding on unreported uses.',extra=['RULE-ROLE'])
    if sid=='AI-008':
        add(r,'RULE-50-4-MEDIA','supported-impact','Reported altered speech and lip movement of real presenters could falsely appear authentic. This supports a proposed deployer disclosure obligation; programme information does not establish the artistic-work adaptation. A visible-label report is not verified compliance.',['ACT-006','ACT-007'],['RULE-DEEPFAKE','REC-009','REC-010','POL-SYNTHETIC','GAP-008-PROVENANCE'])
    elif sid in ['AI-003','AI-007']:
        add(r,'RULE-50-4-MEDIA','supported-no-impact','Reported fictional classroom illustrations or stylized fictional character do not depict an existing entity as an authentic recording. No deepfake-media trigger is supported for this described content; provenance and interaction controls remain separate.',extra=['RULE-DEEPFAKE'])
    elif sid=='AI-005':
        add(r,'RULE-50-4-MEDIA','supported-no-impact','The reported use flags sessions for human review, rather than generating or manipulating deepfake media. This bounded no-impact proposal does not resolve its provider or biometric questions.',extra=['RULE-DEEPFAKE','GAP-005'])
    else:
        add(r,'RULE-50-4-MEDIA','supported-no-impact','No generated or manipulated media resembling an existing entity and falsely appearing authentic is established for this described chat, private drafting, pronunciation or internal-summary use.',extra=['RULE-DEEPFAKE'])
    if sid=='AI-007':
        add(r,'RULE-50-4-TEXT','unresolved','A public programme conversation does not by itself settle public-interest publication purpose or editorial responsibility. Marketing and Legal must establish these facts; no automatic text-disclosure breach or exemption is inferred.',['PROP-007-TEXT'],['POL-DRAFT'])
    elif sid=='AI-002':
        add(r,'RULE-50-4-TEXT','supported-no-impact','Owner context describes private staff drafts, individually reviewed and edited administrative emails, not public-interest publication. Missing recipient notice evidence remains an operational gap; human review alone is not a blanket exemption.',['ACT-003'],['REC-002','POL-DRAFT'])
    elif sid=='AI-006':
        add(r,'RULE-50-4-TEXT','supported-no-impact','Owner context says summaries remain in the restricted staff workspace and are not published or sent to learners, applicants or public. The public-interest publication trigger is absent on the reported facts.',extra=['REC-007'])
    else:
        add(r,'RULE-50-4-TEXT','supported-no-impact','The captured registered use does not establish generated text published to inform the public on matters of public interest. This proposal is limited to the described use and does not approve any unreported publication.')
    if sid=='AI-001':
