def brief_bytes(run, manifest, analysis):
    lines = ["# Regulatory change impact brief", "", f"Run: `{run['run_id']}` · Review date: **{REVIEW_DATE}** · Status: **{analysis['status']}**",
             "", "**Draft for Legal and Operations. All legal interpretations, exceptions, activation, approved dates and incident closure remain pending human decisions. Review requests are prepared and unsent.**",
             "", "Retrieval dates in the source manifest describe actual access, separately from the fixed review date. Detached request bindings are in `deliverables/review-request-bindings.json`; they bind this final draft without a self-referential brief hash.", "", "## Source access and version limits", ""]
    for source in manifest["sources"]:
