        brief_version = {k: v for k, v in version.items() if k not in {"normalized_table", "raw_response", "values", "normalized_records"}}
        version_text = json.dumps(brief_version, ensure_ascii=False)
        if len(version_text) > 1200:
            version_text = "Full identity, version and historical-suitability metadata retained in sources/manifest.json."
        lines.append(f"- `{source['id']}` {source['label']}: **{source['retrieval_status']}**, {source['method']}, retrieved {source['retrieved_at']}. [Route]({source['locator']}). Version metadata: {version_text}. " + (f"Failure: {source['error']}" if source.get("error") else ""))
    lines += ["", "## Supported observations and authority", ""]
    for key in ("binding_rules", "timing_rules", "guidance_context", "system_facts", "policy_controls", "incident_evidence", "unaffected_items"):
        for item in analysis.get(key, []):
            lines.append(f"- `{item['id']}` {item['summary']} Basis: {', '.join('`'+e+'`' for e in item['evidence_ids'])}.")
    lines += ["", "Exact source quotations and locators are retained with these record IDs in `snapshots/03-authority-and-timing.json` and `snapshots/04-evidence-reconciliation.json`; captured bytes and hashes are in `sources/manifest.json`."]
    lines += ["", "## Impact register", "", "| Impact | System / rule | State | Reason | Owner | Proposal / date | Approval |", "|---|---|---|---|---|---|---|"]
    for impact in analysis.get("impacts", []):
