        omitted = "; omitted from calendar: " + action.get("calendar_omission_reason", "unsupported date or blocked dependency") if action.get("calendar_eligible", True) is False else ""
        lines.append(f"- `{aid}` / `{action['system_id']}`: {action.get('action', action['summary'])}. Owner: {action.get('owner') or 'pending Operations'}. Proposed date: {due}{omitted}. Source status: {action.get('status', 'draft')}; required review: {action.get('approval_required') or 'pending'}. Approval: **pending**. Basis: {', '.join(action['evidence_ids'])}. Source version: {action.get('source_version') or 'see manifest'}.")
    lines += ["", "## Legal and Operations review requests", ""]
    for request in analysis.get("approval_requirements", []):
        lines.append(f"- `{request['request_id']}` ({request['id']}): reviewer **{request['required_reviewer']}**; subject {request.get('subject', request.get('subject_system', request.get('subject_impact', request.get('subject_action'))))}; run `{request['run_id']}`; source versions {json.dumps(request['source_versions'], ensure_ascii=False)}. {request['question']} Status: **pending, unsent**. Evidence: {', '.join(request['evidence_ids'])}.")
    lines += ["", "## Limitations", ""]
