            limits = ["Suitable captured version" if version.get("suitable_for_review") is True else "Historical suitability not established"]
        failures = [s for s in attempts if s.get("error")]
        limits.extend(f"{s['id']}: {s['error']}" for s in failures)
        values = (f"[{label}]({source['locator']}): " + "; ".join(f"{s['id']} {s['retrieval_status']}" for s in attempts), identity_version, source["retrieved_at"], " ".join(limits))
        lines.append("| " + " | ".join(md_escape(value) for value in values) + " |")
    lines += ["", "## Authority and timing basis", ""]
    for key in ("binding_rules", "timing_rules", "guidance_context"):
        for item in analysis.get(key, []):
            lines.append(f"- `{item['id']}` {item['summary']} Basis: {', '.join('`'+e+'`' for e in item['evidence_ids'])}.")
    lines += ["", "Exact quotations, locators and company facts remain in `snapshots/03-authority-and-timing.json` and `snapshots/04-evidence-reconciliation.json`; evidence states do not establish compliance."]
    impacts = analysis.get("impacts", [])
    counts = {state: sum(i["state"] == state for i in impacts) for state in ("supported-impact", "supported-no-impact", "conflicting", "unresolved")}
    lines += ["", "## Findings", "", "; ".join(f"{count} {state}" for state, count in counts.items()) + ". Full rule, evidence and proposal reasoning is in `impact-register.csv`.", "",
              "| Impact / system / rule | State | Finding | Owner / linked proposals |", "|---|---|---|---|"]
    for impact in [i for i in impacts if i["state"] != "supported-no-impact"]:
        action_ids = impact.get("action_ids", []) or [a.get("action_id", a["id"]) for a in analysis.get("proposed_actions", []) if impact["id"] in a.get("impact_ids", [])]
        values = (f"{impact['id']} / {impact['system_id']} / {impact['rule_ref']}", impact["state"], impact["summary"], (impact.get("owner") or "pending assignment") + " / " + (", ".join(action_ids) or "none proposed"))
        lines.append("| " + " | ".join(md_escape(v) for v in values) + " |")
    no_impact = {}
    for impact in [i for i in impacts if i["state"] == "supported-no-impact"]:
        no_impact.setdefault(impact["system_id"], []).append(impact)
    if no_impact:
        lines += ["", "Bounded **supported-no-impact** proposals (specific rules and observed uses; no blanket compliance conclusion):"]
        for system, findings in sorted(no_impact.items()):
            lines.append(f"- `{system}`: " + "; ".join(f"`{i['id']}` / `{i['rule_ref']}`" for i in findings) + ". See the cited CSV rows for the complete limitations and source basis.")
    for item in analysis.get("unaffected_items", []):
        lines.append(f"- `{item['id']}` {item['summary']} (basis: {', '.join(item['evidence_ids'])}).")
