        for item in analysis.get(key, []):
            if item["id"] in seen:
                continue
            seen.add(item["id"])
            lines.append(f"- `{item['id']}` {item['summary']} Owner: {item.get('owner') or 'pending assignment'}. Resolution: {item.get('resolution_need', item.get('question', 'see linked request'))}. Basis: {', '.join(item['evidence_ids'])}.")
    lines += ["", "## Proposed actions and calendar", ""]
    for action in analysis.get("proposed_actions", []):
        aid = action.get("action_id", action["id"])
        due = action.get("due_date") or "undated, omitted from calendar pending Operations"
        omitted = "; omitted from calendar: " + action.get("calendar_omission_reason", "unsupported date or blocked dependency") if action.get("calendar_eligible", True) is False else ""
        lines.append(f"- `{aid}` / `{action['system_id']}`: {action.get('action', action['summary'])}. {action.get('owner') or 'pending Operations'}; proposed **{due}**{omitted}; source status {action.get('status', 'draft')}; review {action.get('approval_required') or 'pending'}; approval **pending**. Basis: {', '.join(action['evidence_ids'])}.")
    lines += ["", "## Legal and Operations review requests", ""]
    lines += ["Each request below is **pending and unsent**, bound to this run and to the exact source versions and final draft hashes in `review-request-bindings.json` (matching `request_id`); full request evidence is in snapshot 06.", ""]
    for request in analysis.get("approval_requirements", []):
        subject = "; ".join(str(request[k]) for k in ("subject", "subject_system", "subject_impact", "subject_action") if request.get(k))
        lines.append(f"- `{request['request_id']}` ({request['id']}), **{request['required_reviewer']}**, {subject}: {request['question']}")
    lines += ["", "## Limitations", ""]
    lines.extend("- " + limitation for limitation in analysis.get("limitations", []))
    lines += ["", "## Recorded workflow decisions", ""]
    for decision in analysis.get("decisions", []):
        lines.append(f"- `{decision['id']}` {decision['summary']} Rationale: {decision['rationale']} Tradeoffs: {'; '.join(decision['tradeoffs'])}. Evidence: {', '.join(decision['evidence_ids'])}.")
    return ("\n".join(lines) + "\n").encode("utf-8")


