transcript_blob=gh('git/blobs/'+remote['main']['interviews/project-b-regulatory-compliance-20261008-1603.md']);transcript=base64.b64decode(transcript_blob['content']);sha=hashlib.sha256(transcript).hexdigest();assert sha=='02a8e16ff1f8492fdb9ae5a9bbf7e5728e80aff621cd96a4697f472b1e12d4e2';result['remote_interview_sha256']=sha
Path('/tmp/project-b-remote-verification.json').write_text(json.dumps(result,indent=2)+'\n')
